mapper.update:
UPDATE soar_playbook SET status = 'disabled', enabled = FALSE, deleted_at = CURRENT_TIMESTAMP,
  updated_by = #{actor,jdbcType=VARCHAR}, updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId,jdbcType=VARCHAR} AND id = #{id,jdbcType=VARCHAR}

mapper.select:
SELECT id FROM soar_execution WHERE id = #{id,jdbcType=VARCHAR}
  AND status = 'running' AND cancel_requested = FALSE AND lease_owner = #{owner,jdbcType=VARCHAR}
  AND version = #{fencingToken,jdbcType=BIGINT} AND lease_expires_at >= CURRENT_TIMESTAMP
  FOR UPDATE

mapper.update:
UPDATE soar_execution SET status = 'waiting', current_node_id = NULL,
  next_run_at = #{nextRunAt,jdbcType=TIMESTAMP}, lease_owner = NULL, lease_expires_at = NULL,
  updated_at = CURRENT_TIMESTAMP, version = version + 1
WHERE id = #{id,jdbcType=VARCHAR} AND status = 'running' AND lease_owner = #{owner,jdbcType=VARCHAR}
  AND version = #{fencingToken,jdbcType=BIGINT}

UPDATE soar_execution SET status = 'pending', current_node_id = #{currentNodeId,jdbcType=VARCHAR},
  payload_snapshot = #{payloadSnapshot,jdbcType=VARCHAR}, next_run_at = CURRENT_TIMESTAMP,
  lease_owner = NULL, lease_expires_at = NULL, updated_at = CURRENT_TIMESTAMP,
  version = version + 1
WHERE id = #{id,jdbcType=VARCHAR} AND status = 'running' AND lease_owner = #{owner,jdbcType=VARCHAR}
  AND version = #{fencingToken,jdbcType=BIGINT}

UPDATE soar_node_execution SET input_json = #{inputJson,jdbcType=VARCHAR}
WHERE id = #{id,jdbcType=VARCHAR} AND execution_id = #{executionId,jdbcType=VARCHAR}
  AND status = 'running'

UPDATE soar_node_execution SET status = 'waiting'
WHERE id = #{nodeRunId,jdbcType=VARCHAR} AND execution_id = #{executionId,jdbcType=VARCHAR}
  AND status = 'running'

UPDATE soar_node_execution SET status = 'waiting_human'
WHERE id = #{nodeRunId,jdbcType=VARCHAR} AND execution_id = #{executionId,jdbcType=VARCHAR}
  AND status = 'running'

UPDATE soar_node_execution SET status = 'cancelled', finished_at = CURRENT_TIMESTAMP
WHERE execution_id = #{executionId}
  AND status IN ('running','waiting','waiting_human','retrying')

UPDATE soar_node_execution SET status = 'failed', error = #{error,jdbcType=VARCHAR},
  finished_at = CURRENT_TIMESTAMP
WHERE id = #{id,jdbcType=VARCHAR}

mapper.select:
SELECT b.id, b.group_id, g.parent_execution_id, g.join_node_id,
  b.branch_label, b.target_node_id
FROM soar_parallel_branch b JOIN soar_parallel_group g ON g.id = b.group_id
WHERE b.execution_id = #{executionId,jdbcType=VARCHAR}
  AND b.status IN ('pending','running') AND g.status = 'waiting' AND g.join_node_id = #{nodeId,jdbcType=VARCHAR}

SELECT id, parent_execution_id, parent_node_run_id
FROM soar_loop_state WHERE child_execution_id = #{childExecutionId,jdbcType=VARCHAR}
  AND status = 'running' FOR UPDATE
